excels.excel:

EXPORT WITH SHEET="月度费用预算执行偏差对比表", HEADER=true,
    MAPPING={"a":"费用项目","b":"预算金额","c":"实际支出","d":"偏差金额","e":"偏差率","f":"控制结论"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'B2-C2',E2:'D2/B2',D3:'B3-C3',E3:'D3/B3',D4:'B4-C4',E4:'D4/B4',
        D5:'B5-C5',E5:'D5/B5',D6:'B6-C6',E6:'D6/B6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'B7-C7',E7:'D7/B7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        D3:{color:red,bold:true}
    }
